include("evaluate.jl")

# 100K expression performance
n = 50000
expr = repeat("1+", n-1) * "1"
println("Expression length: $(length(expr))")
t = @elapsed result = evaluate(expr)
println("Result: $(result) in $(round(t*1000,2)) ms")

# Error messages contain position
for (s, expected_substr) in [
    ("1 +", "unexpected character"),
    ("1 2", "unexpected character"),
    ("(", "missing closing"),
    ("", "unexpected character"),
]
    try evaluate(s)
    catch e
        ok = occursin(expected_substr, e.msg) && occursin("position", e.msg)
        println("$ok: \"$s\" → $(e.msg[1:80])...")
    end
end

# Key precedence checks
@test = (a,b) -> println("$a == $b : $(a==b)")
@test evaluate("-2^2") (-4.0)
@test evaluate("2^-2") (0.25)
@test evaluate("2^2^3") (256.0)
@test evaluate("2^3*2") (16.0)
@test evaluate("- -2") (2.0)
@test evaluate("(-2)^2") (4.0)
@test evaluate("2* -3") (-6.0)
@test evaluate("(-2)^3") (-8.0)
'

